const Component = ({ item }) => {
 const frame = useCurrentFrame();
 const p = item.props;
 const rows = JSON.parse(p.captionJson);
 let active = null;
 for (const row of rows) { if (frame >= row.start && frame < row.end) active = row; }
 const rootStyle = { position: "absolute", inset: 0, backgroundColor: p.transparentBackground ? "transparent" : p.ink, fontFamily: p.fontFamily, pointerEvents: "none" };
 const headerStyle = { position: "absolute", top: 108, left: 48, right: 48, display: "flex", flexDirection: "column", alignItems: "center", gap: 8 };
 const specs = [{text:p.hook,size:60,color:p.yellow,stroke:p.blue},{text:p.product,size:76,color:p.blue,stroke:p.cream},{text:p.sellingPoint,size:61,color:p.red,stroke:p.white},{text:p.taste,size:63,color:p.cream,stroke:p.red}];
 const headerLines = specs.map((s,n) => { const style = { fontSize:s.size, fontWeight:900, lineHeight:1.15, textAlign:"center", maxWidth:984, whiteSpace:"normal", overflowWrap:"break-word", color:s.color, WebkitTextStroke:"4px " + s.stroke, paintOrder:"stroke fill", textShadow:"1px 2px 0 " + p.ink }; return <div key={n} style={style}>{s.text}</div>; });
 const captionStyle = { position:"absolute", bottom:280, left:58, right:58, textAlign:"center", fontSize:p.captionSize, fontWeight:800, lineHeight:1.24, color:p.white, WebkitTextStroke:"3px " + p.ink, paintOrder:"stroke fill", textShadow:"0px 2px 2px rgba(0,0,0,0.45)", whiteSpace:"normal", overflowWrap:"break-word" };
 const text = active ? active.text : "";
 const parts = text.split(/(鲜果|水果|团购|尝鲜)/g);
 const captionParts = parts.map((part,n) => { const keyWord = ["鲜果","水果","团购","尝鲜"].includes(part); const style = {color:keyWord ? p.yellow : p.white}; return <span key={n} style={style}>{part}</span>; });
 return <div style={rootStyle}><div style={headerStyle}>{headerLines}</div><div style={captionStyle}>{captionParts}</div></div>;
};
